package org.localscape.nylocas.ranger;
import org.junit.Test;import org.localscape.nylocas.ranger.RangerStrategy.*;import static org.junit.Assert.*;
public class RangerWestNineteenCoveredFollowupTest {
 private Crab west,south,east;private RangerStrategy strategy;
 private Crab add(Room r,int key,int born,int wave,Lane lane,boolean big,Style style,int x,int y){Crab c=new Crab(key,key,born,wave,lane,'S',big,style,RangerStrategy.tile(x,y));c.pendingDamage=0;r.crabs.add(c);return c;}
 private Room room(){Room r=new Room();r.wave=19;r.spawns[18]=140;r.spawns[19]=148;r.ready=158;r.player=RangerStrategy.tile(3293,4246);for(int i=0;i<3;i++)add(r,80+i,124,17,Lane.values()[i],true,Style.MELEE,3299,4251);add(r,72,112,15,Lane.SOUTH,true,Style.MAGIC,3292,4244);Crab body=add(r,87,140,18,Lane.WEST,true,Style.RANGE,3290,4248);body.hp=0;body.dying=true;south=add(r,88,140,18,Lane.SOUTH,true,Style.RANGE,3292,4243);south.pendingDamage=16;east=add(r,89,140,18,Lane.EAST,true,Style.RANGE,3292,4253);west=add(r,90,148,19,Lane.WEST,true,Style.MAGIC,3291,4249);west.hp=14;west.pendingDamage=7;add(r,91,148,19,Lane.SOUTH,true,Style.MAGIC,3293,4243);add(r,92,148,19,Lane.EAST,true,Style.MAGIC,3297,4248);strategy=new RangerStrategy();strategy.attacked(new Decision(west,Weapon.EYE,r.player,false,null,"actualEye3"),151);strategy.attacked(new Decision(south,Weapon.PIPE,r.player,false,null,"actualcovered18"),156);return r;}
 @Test public void nativeKnownEighteenCoverageReleasesOneSupportedWestFollowup(){Room r=room();Decision d=strategy.decide(r,158);assertSame(d.reason,west,d.target);assertEquals(Weapon.EYE,d.weapon);}
 @Test public void actualNonlethalEighteenSurvivorKeepsItsFollowup(){Room r=room();south.pendingDamage=7;assertSame(south,strategy.decide(r,158).target);}
 @Test public void earliestTwentyBowAndRemainingFullParentsBoundTheOption(){Room r=room();r.spawns[19]=147;assertSame(east,strategy.decide(r,158).target);r=room();south.pendingDamage=0;strategy=new RangerStrategy();strategy.attacked(new Decision(west,Weapon.EYE,r.player,false,null,"actualEye3"),151);assertNotSame(west,strategy.decide(r,158).target);}
 @Test public void noPriorRangerOpeningOrMoreThanEightKnownRemainingDamageKeepsParentService(){Room r=room();strategy=new RangerStrategy();assertSame(east,strategy.decide(r,158).target);r=room();west.hp=16;west.pendingDamage=0;assertSame(east,strategy.decide(r,158).target);}
 @Test public void actualCapClearanceSmallStaysAboveThisOptionalFollowup(){Room r=room();r.ready=156;Crab small=add(r,94,154,19,Lane.SPLIT,false,Style.RANGE,3293,4247);small.hp=3;assertSame(small,strategy.decide(r,156).target);}
 @Test public void aRealOtherSmallSurvivorCannotTriggerTheNewTier(){Room r=room();Crab small=add(r,94,154,19,Lane.SPLIT,false,Style.RANGE,3293,4247);small.hp=3;strategy.attacked(new Decision(small,Weapon.PIPE,r.player,false,null,"actualsmall"),156);assertNotSame(west,strategy.decide(r,158).target);}
 @Test public void unknownLethalNullBlockedAndDistantWestCannotCreateTheOption(){for(int g=0;g<5;g++){Room r=room();if(g==0)west.pendingDamage=-1;if(g==1)west.pendingDamage=west.hp;if(g==2)west.nulled=true;if(g==3)r.obstructed.add(west.key);if(g==4)west.point=RangerStrategy.tile(3281,4248);assertNotSame("guard"+g,west,strategy.decide(r,158).target);}}
 @Test public void unknownEighteenWorkCannotBePromised(){Room r=room();east.pendingDamage=-1;assertNotSame(west,strategy.decide(r,158).target);}
 @Test public void noNewCooldownApproachAndNoPostAdmissionPriority(){Room r=room();r.ready=159;assertNotSame(west,strategy.decide(r,158).target);r=room();r.wave=20;r.spawns[20]=160;assertNotSame(west,strategy.decide(r,160).target);}
}